#!/usr/local/bin/prhm-node
'use strict';
const fs=require('fs');
const path=require('path');
const crypto=require('crypto');
const cp=require('child_process');

const TARGET='/opt/prhm-project-factory/factory.js';
const EXPECTED_SHA='44eb74b4af1e028f12430d9dff992fbc17b650a5c689ca48764eca737befc46a';
const BACKUP_ROOT='/var/backups/prhm-project-factory-v1-3-4';
const ROOT_BASE='/home/prhm/projects/generated';
const NODE='/usr/local/bin/prhm-node';
const NODE_BIN='/opt/prhm-project-factory/node/bin';
const NPM=NODE_BIN+'/npm';

function sha(buf){return crypto.createHash('sha256').update(buf).digest('hex');}
function die(msg){throw new Error(msg);}
function replaceOnce(text,oldText,newText,label){const i=text.indexOf(oldText);if(i<0)die('missing_anchor:'+label);if(text.indexOf(oldText,i+oldText.length)>=0)die('duplicate_anchor:'+label);return text.slice(0,i)+newText+text.slice(i+oldText.length);}
function run(cmd,args,opts={}){return cp.spawnSync(cmd,args,{encoding:'utf8',maxBuffer:32*1024*1024,...opts});}
function assertZero(r,label){if(r.error)die(label+'_spawn:'+r.error.message);if(r.status!==0)die(label+'_exit:'+r.status+':'+String(r.stderr||r.stdout||'').slice(-5000));}
function regularFile(f){try{return fs.statSync(f).isFile();}catch{return false;}}
function atomicWrite(target,content,st){const tmp=target+'.tmp-v1-3-4-'+process.pid;fs.writeFileSync(tmp,content,{mode:st.mode&0o777});fs.chownSync(tmp,st.uid,st.gid);fs.chmodSync(tmp,st.mode&0o777);fs.renameSync(tmp,target);}
function versionsFromLock(lock,name){const out=[];for(const [k,v] of Object.entries(lock.packages||{})){if(k==='node_modules/'+name||k.endsWith('/node_modules/'+name)){if(v&&v.version)out.push({path:k,version:v.version});}}return out;}
function tuple(v){return String(v).split('.').slice(0,3).map(x=>parseInt(x,10)||0);}
function lt(a,b){const A=tuple(a),B=tuple(b);for(let i=0;i<3;i++){if(A[i]<B[i])return true;if(A[i]>B[i])return false;}return false;}
function cleanProject(root,slug){if(!fs.existsSync(root))return;const mf=path.join(root,'.prhm','project.json');if(!regularFile(mf))die('cleanup_manifest_missing:'+slug);const m=JSON.parse(fs.readFileSync(mf,'utf8'));if(m.standard_id!=='PRHM_NEW_SITE_V1'||m.slug!==slug||!m.features||m.features.security_v134_e2e!==true)die('cleanup_manifest_guard:'+slug);fs.rmSync(root,{recursive:true,force:false,maxRetries:3,retryDelay:250});if(fs.existsSync(root))die('cleanup_failed:'+slug);}
function securityEnv(){return{...process.env,PATH:NODE_BIN+':'+(process.env.PATH||''),CI:'1',HOME:'/var/lib/prhm-project-factory',XDG_CONFIG_HOME:'/var/lib/prhm-project-factory/config',npm_config_cache:'/var/lib/prhm-project-factory/npm-cache'};}
function auditDir(dir,label){const r=run(NPM,['--prefix',dir,'audit','--json','--workspaces=false'],{cwd:'/tmp',env:securityEnv(),timeout:300000});let obj={};try{obj=JSON.parse(String(r.stdout||'').trim()||'{}');}catch(e){die(label+'_audit_json:'+e.message);}const v=obj.metadata?.vulnerabilities||{};return{exit_code:r.status,info:v.info||0,low:v.low||0,moderate:v.moderate||0,high:v.high||0,critical:v.critical||0,total:v.total||0};}

function main(){
  const current=fs.readFileSync(TARGET);const currentSha=sha(current);if(currentSha!==EXPECTED_SHA)die('sha_mismatch:'+currentSha);
  const original=current.toString('utf8');const st=fs.statSync(TARGET);
  const stamp=new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);
  fs.mkdirSync(BACKUP_ROOT,{recursive:true,mode:0o700});const backup=path.join(BACKUP_ROOT,'factory.js.'+stamp+'.bak');fs.writeFileSync(backup,current,{mode:0o600});

  let patched=replaceOnce(original,"const FACTORY_VERSION='1.3.3';","const FACTORY_VERSION='1.3.4';",'version');
  const oldPin='create-next-app@16.2.11',newPin='create-next-app@16.2.12';
  const oldCount=patched.split(oldPin).length-1;if(oldCount!==2)die('unexpected_old_pin_count:'+oldCount);patched=patched.split(oldPin).join(newPin);if((patched.split(newPin).length-1)!==2)die('new_pin_count_failed');

  const webLine="{name:'next_web',command:'/opt/prhm-project-factory/node/bin/npx',args:['create-next-app@16.2.12',path.join(root,'apps/web'),'--ts','--tailwind','--eslint','--app','--src-dir','--import-alias','@/*','--use-npm','--yes','--disable-git'],cwd:root},";
  const adminLine="{name:'next_admin',command:'/opt/prhm-project-factory/node/bin/npx',args:['create-next-app@16.2.12',path.join(root,'apps/admin'),'--ts','--tailwind','--eslint','--app','--src-dir','--import-alias','@/*','--use-npm','--yes','--disable-git'],cwd:root},";
  patched=replaceOnce(patched,webLine,webLine+"\n{name:'next_web_security',command:'__prhm_next_security__',args:[path.join(root,'apps/web')],cwd:path.join(root,'apps/web')},",'web_security_step');
  patched=replaceOnce(patched,adminLine,adminLine+"\n{name:'next_admin_security',command:'__prhm_next_security__',args:[path.join(root,'apps/admin')],cwd:path.join(root,'apps/admin')},",'admin_security_step');

  const runAnchor="function run(s){mkdirp(XDG_CONFIG_HOME);const started_at=new Date().toISOString();const r=spawnSync(s.command,s.args,{cwd:s.cwd,stdio:'inherit',timeout:900000,env:{...process.env,CI:'1',HOME:FACTORY_STATE,XDG_CONFIG_HOME,COMPOSER_HOME:path.join(FACTORY_STATE,'composer'),npm_config_cache:path.join(FACTORY_STATE,'npm-cache')}});return{name:s.name,command:s.command,args:s.args,cwd:s.cwd,started_at,finished_at:new Date().toISOString(),exit_code:Number.isInteger(r.status)?r.status:null,signal:r.signal||null,error:r.error?r.error.message:null};}";
  const runReplacement=`function nodeEnv(extra={}){return{...process.env,CI:'1',HOME:FACTORY_STATE,XDG_CONFIG_HOME,COMPOSER_HOME:path.join(FACTORY_STATE,'composer'),npm_config_cache:path.join(FACTORY_STATE,'npm-cache'),...extra};}\nfunction vtuple(v){return String(v).split('.').slice(0,3).map(x=>parseInt(x,10)||0);}\nfunction semverLt(a,b){const A=vtuple(a),B=vtuple(b);for(let i=0;i<3;i++){if(A[i]<B[i])return true;if(A[i]>B[i])return false;}return false;}\nfunction lockVersions(lock,name){const out=[];for(const [k,v] of Object.entries(lock.packages||{})){if(k==='node_modules/'+name||k.endsWith('/node_modules/'+name)){if(v&&v.version)out.push({path:k,version:v.version});}}return out;}\nfunction runNextSecurity(s){mkdirp(XDG_CONFIG_HOME);const started_at=new Date().toISOString(),app=s.cwd,pkgFile=path.join(app,'package.json'),lockFile=path.join(app,'package-lock.json'),npm='/opt/prhm-project-factory/node/bin/npm',env=nodeEnv({PATH:'/opt/prhm-project-factory/node/bin:'+(process.env.PATH||'')});try{if(!regularFile(pkgFile))throw new Error('package_json_missing');const pkg=JSON.parse(fs.readFileSync(pkgFile,'utf8'));if(pkg.dependencies?.next!=='16.2.12')throw new Error('next_version:'+String(pkg.dependencies?.next));pkg.overrides={...(pkg.overrides||{}),postcss:'8.5.23',sharp:'0.35.3'};fs.writeFileSync(pkgFile,JSON.stringify(pkg,null,2)+'\\n',{mode:0o640});const install=spawnSync(npm,['--prefix',app,'install','--no-audit','--no-fund','--workspaces=false'],{cwd:'/tmp',stdio:'inherit',timeout:900000,env});if(install.error||install.status!==0)throw new Error('npm_install:'+String(install.error?.message||install.status));if(!regularFile(lockFile))throw new Error('package_lock_missing');const audit=spawnSync(npm,['--prefix',app,'audit','--json','--workspaces=false'],{cwd:'/tmp',encoding:'utf8',maxBuffer:16*1024*1024,timeout:300000,env});let auditObj;try{auditObj=JSON.parse(String(audit.stdout||'').trim()||'{}');}catch(e){throw new Error('audit_json:'+e.message);}const vul=auditObj.metadata?.vulnerabilities||{};if((vul.high||0)>0||(vul.critical||0)>0)throw new Error('audit_high_or_critical:'+JSON.stringify(vul));const tree=spawnSync(npm,['--prefix',app,'ls','next','postcss','sharp','--json','--all','--workspaces=false'],{cwd:'/tmp',encoding:'utf8',maxBuffer:16*1024*1024,timeout:300000,env});if(tree.error||tree.status!==0)throw new Error('npm_ls:'+String(tree.error?.message||tree.status));const build=spawnSync(npm,['--prefix',app,'run','build','--workspaces=false'],{cwd:'/tmp',stdio:'inherit',timeout:900000,env});if(build.error||build.status!==0)throw new Error('next_build:'+String(build.error?.message||build.status));const lock=JSON.parse(fs.readFileSync(lockFile,'utf8')),next=lockVersions(lock,'next'),postcss=lockVersions(lock,'postcss'),sharp=lockVersions(lock,'sharp');if(next.length<1||next.some(x=>x.version!=='16.2.12'))throw new Error('resolved_next:'+JSON.stringify(next));if(postcss.length<1||postcss.some(x=>semverLt(x.version,'8.5.23')))throw new Error('resolved_postcss:'+JSON.stringify(postcss));if(sharp.length<1||sharp.some(x=>semverLt(x.version,'0.35.0')))throw new Error('resolved_sharp:'+JSON.stringify(sharp));try{fs.rmSync(path.join(app,'.next'),{recursive:true,force:true,maxRetries:3,retryDelay:100});}catch{}const details={audit:{info:vul.info||0,low:vul.low||0,moderate:vul.moderate||0,high:vul.high||0,critical:vul.critical||0,total:vul.total||0},resolved:{next,postcss,sharp},build_exit:0};console.log('PRHM_NEXT_SECURITY_OK='+JSON.stringify({app,audit:details.audit}));return{name:s.name,command:s.command,args:s.args,cwd:s.cwd,started_at,finished_at:new Date().toISOString(),exit_code:0,signal:null,error:null,details};}catch(e){return{name:s.name,command:s.command,args:s.args,cwd:s.cwd,started_at,finished_at:new Date().toISOString(),exit_code:1,signal:null,error:'next_security:'+e.message};}}\nfunction run(s){if(s.command==='__prhm_next_security__')return runNextSecurity(s);mkdirp(XDG_CONFIG_HOME);const started_at=new Date().toISOString();const r=spawnSync(s.command,s.args,{cwd:s.cwd,stdio:'inherit',timeout:900000,env:nodeEnv()});return{name:s.name,command:s.command,args:s.args,cwd:s.cwd,started_at,finished_at:new Date().toISOString(),exit_code:Number.isInteger(r.status)?r.status:null,signal:r.signal||null,error:r.error?r.error.message:null};}`;
  patched=replaceOnce(patched,runAnchor,runReplacement,'run_security');

  const artifactAnchor="function stepArtifacts(s){switch(s.name){case'laravel_api':return[path.join(s.args[2],'artisan'),path.join(s.args[2],'composer.json')];case'laravel_standard_packages':return[path.join(s.cwd,'composer.json'),path.join(s.cwd,'composer.lock')];case'next_web':case'next_admin':return[path.join(s.args[1],'package.json')];case'git_init':return[path.join(s.cwd,'.git/HEAD')];default:return[];}}";
  const artifactReplacement="function stepArtifacts(s){switch(s.name){case'laravel_api':return[path.join(s.args[2],'artisan'),path.join(s.args[2],'composer.json')];case'laravel_standard_packages':return[path.join(s.cwd,'composer.json'),path.join(s.cwd,'composer.lock')];case'next_web':case'next_admin':return[path.join(s.args[1],'package.json')];case'next_web_security':case'next_admin_security':return[path.join(s.cwd,'package.json'),path.join(s.cwd,'package-lock.json')];case'git_init':return[path.join(s.cwd,'.git/HEAD')];default:return[];}}";
  patched=replaceOnce(patched,artifactAnchor,artifactReplacement,'security_artifacts');

  if(!patched.includes("const FACTORY_VERSION='1.3.4';"))die('version_patch_missing');
  if(patched.includes(oldPin))die('old_pin_remaining');
  if((patched.split("command:'__prhm_next_security__'").length-1)!==2)die('security_step_count_failed');

  const candidate=TARGET+'.candidate-v1-3-4-'+process.pid+'.js';fs.writeFileSync(candidate,patched,{mode:0o600});
  const slug='factory-v134-security-e2e-'+stamp.slice(8,14).toLowerCase(),root=path.join(ROOT_BASE,slug);
  try{
    const syntax=run(NODE,['--check',candidate]);assertZero(syntax,'candidate_syntax');
    atomicWrite(TARGET,Buffer.from(patched,'utf8'),st);const installed=fs.readFileSync(TARGET),installedSha=sha(installed);if(installed.toString('utf8')!==patched)die('postwrite_bytes_mismatch');

    const dryManifest={standard_id:'PRHM_NEW_SITE_V1',slug:'factory-v134-dryrun',name:'Factory v1.3.4 dry run',domains:['factory-v134-dryrun.invalid'],languages:['fa'],modules:['auth'],payment_adapter:null,sms_adapter:null,brand:{display_name:'Factory v1.3.4'},features:{security_upgrade_test:true}};
    const dry=run(NODE,[TARGET,'--dry-run','--manifest-base64',Buffer.from(JSON.stringify(dryManifest)).toString('base64')],{env:{...process.env,PATH:NODE_BIN+':'+(process.env.PATH||'')}});assertZero(dry,'dry_run');const plan=JSON.parse(String(dry.stdout||'').trim());if(!plan.ok||!plan.dry_run||plan.factory_version!=='1.3.4')die('dry_run_semantics_failed');const names=(plan.steps||[]).map(x=>x.name);for(const n of ['next_web','next_web_security','next_admin','next_admin_security'])if(!names.includes(n))die('dry_run_missing_step:'+n);const nextSteps=(plan.steps||[]).filter(x=>x.name==='next_web'||x.name==='next_admin');if(nextSteps.length!==2||nextSteps.some(x=>x.args[0]!==newPin))die('dry_run_pin_verify_failed');

    const manifest={standard_id:'PRHM_NEW_SITE_V1',slug,name:'Project Factory v1.3.4 security E2E',domains:[slug+'.invalid'],languages:['fa'],modules:['auth'],payment_adapter:null,sms_adapter:null,brand:{display_name:'Factory v1.3.4 Security E2E'},features:{security_v134_e2e:true}};
    const e2e=run(NODE,[TARGET,'--manifest-base64',Buffer.from(JSON.stringify(manifest)).toString('base64')],{timeout:1800000,env:{...process.env,PATH:NODE_BIN+':'+(process.env.PATH||'')}});assertZero(e2e,'e2e');if(!String(e2e.stdout||'').includes('PRHM_BOOTSTRAP_OK='+root))die('e2e_success_marker_missing');

    const stateFile=path.join(root,'.prhm','bootstrap-state.json');if(!regularFile(stateFile))die('e2e_state_missing');const state=JSON.parse(fs.readFileSync(stateFile,'utf8'));if(!state.ok||state.status!=='ready_for_configuration'||state.factory_version!=='1.3.4')die('e2e_state_semantics');for(const n of ['next_web_security','next_admin_security']){const s=(state.steps||[]).find(x=>x.name===n);if(!s||s.exit_code!==0||s.error)die('e2e_security_step_failed:'+n);if((s.details?.audit?.high||0)!==0||(s.details?.audit?.critical||0)!==0||s.details?.build_exit!==0)die('e2e_security_evidence_failed:'+n);}
    for(const app of ['web','admin']){const dir=path.join(root,'apps',app),pkg=JSON.parse(fs.readFileSync(path.join(dir,'package.json'),'utf8'));if(pkg.dependencies?.next!=='16.2.12')die(app+'_next:'+pkg.dependencies?.next);if(pkg.overrides?.postcss!=='8.5.23'||pkg.overrides?.sharp!=='0.35.3')die(app+'_overrides');const lock=JSON.parse(fs.readFileSync(path.join(dir,'package-lock.json'),'utf8')),nv=versionsFromLock(lock,'next'),pv=versionsFromLock(lock,'postcss'),sv=versionsFromLock(lock,'sharp');if(nv.length<1||nv.some(x=>x.version!=='16.2.12'))die(app+'_lock_next:'+JSON.stringify(nv));if(pv.length<1||pv.some(x=>lt(x.version,'8.5.23')))die(app+'_lock_postcss:'+JSON.stringify(pv));if(sv.length<1||sv.some(x=>lt(x.version,'0.35.0')))die(app+'_lock_sharp:'+JSON.stringify(sv));const audit=auditDir(dir,app);if(audit.high||audit.critical)die(app+'_audit:'+JSON.stringify(audit));console.log(app.toUpperCase()+'_AUDIT='+JSON.stringify(audit));}

    console.log('PROJECT_FACTORY_V134_APPLY_OK=1');console.log('BACKUP='+backup);console.log('OLD_SHA='+EXPECTED_SHA);console.log('NEW_SHA='+installedSha);console.log('E2E_STATE_SHA='+sha(fs.readFileSync(stateFile)));
    cleanProject(root,slug);console.log('E2E_CLEANUP_OK=1');
  }catch(e){try{cleanProject(root,slug);}catch(cleanErr){console.error('E2E_CLEANUP_ERROR='+cleanErr.message);}try{atomicWrite(TARGET,current,st);console.error('ROLLBACK_TO_OLD_SHA='+sha(fs.readFileSync(TARGET)));}catch(rb){console.error('ROLLBACK_FAILED='+rb.message);}throw e;}finally{try{fs.unlinkSync(candidate);}catch{}}
}
try{main();}catch(e){console.error('PROJECT_FACTORY_V134_APPLY_ERROR='+e.message);process.exit(1);}
